1513		Using the self-consistency of $\{M^{(\Point,W),u}_a\}$ shown in Lemma~\ref{lem:qld-win-implications}, we then obtain
1514		\begin{align}
1515			\text{\eqref{eq:qld-pulling-2b}} &\approx_{\eps} \sum_{\substack{g,h: \\ (\coded(g)-h)\cdot \tilde{u} = a}} (\hat{S}^W_g)_{\alice \alice'} \cdot \Big((M^{(\Point,W),u}_{(g-g_h)(u)})_{\alice} \otimes (\tau_h^W)_{\alice''} \Big) \cdot \Big ( M^{(\Point,W),u}_{(g-g_h)(u)} \Big)_{\bob} \label{eq:qld-pulling-3} \\
1516			&\approx_{0}\sum_{\substack{g,h: \\ (\coded(g)-h)\cdot \tilde{u} = a}} (\hat{S}^W_g)_{\alice \alice'} \cdot \Big((M^{(\Point,W),u}_{(g-g_h)(u)})_{\alice} \otimes (\tau_h^W)_{\alice'} \otimes (\tau_h^W)_{\alice''} \Big) \cdot \Big ( M^{(\Point,W),u}_{(g-g_h)(u)} \Big)_{\bob} \label{eq:qld-pulling-3a} \\
1517			&= \sum_{\substack{g,h: \\ (\coded(g)-h)\cdot \tilde{u} = a}} (\hat{S}^W_g)_{\alice \alice'} \cdot \Big((\hat{M}^{(\Point,W),u}_{g(u)})_{\alice \alice'} \otimes (\tau_h^W)_{\alice''} \Big) \cdot \Big ( M^{(\Point,W),u}_{(g-g_h)(u)} \Big)_{\bob} \;. \label{eq:qld-pulling-3b}
1518		\end{align}
1519		The ``$\approx_0$'' in Line~\eqref{eq:qld-pulling-3a} indicates that the left hand side is equal to the right hand side when applied to the state $\ket{\hat{\psi}}$. Line~\eqref{eq:qld-pulling-3a} follows from the self-consistency of the operators $\{\tau^W_h\}$, and Line~\eqref{eq:qld-pulling-3b} follows from the definition of $\{ \hat{M}^{(\Point,W),u}_a\}$. Using the fact that $\ket{\hat{\psi}} = \sum_{h'} (\tau^W_{h'})_{\bob'} \otimes (\tau^W_{h'})_{\bob''} \ket{\hat{\psi}}$, we get that 
1520		\begin{align}
1521		\text{\eqref{eq:qld-pulling-3b}} & \approx_0 \sum_{\substack{g,h: \\ (\coded(g)-h)\cdot \tilde{u} = a}} \Big((\hat{S}^W_g \cdot \hat{M}^{(\Point,W),u}_{g(u)})_{\alice \alice'} \otimes (\tau_h^W)_{\alice''} \Big) \cdot \Big( M^{(\Point,W),u}_{(g-g_h)(u)} \otimes \sum_{h'} \tau_{h'}^W \otimes \tau_{h'}^W\Big)_{\bob \bob' \bob''} \label{eq:qld-pulling-4} \\
1522			&= \sum_{\substack{g,h,h': \\ (\coded(g)-h)\cdot \tilde{u} = a}} \Big((\hat{S}^W_g \cdot \hat{M}^{(\Point,W),u}_{g(u)})_{\alice \alice'} \otimes (\tau_h^W)_{\alice''} \Big) \cdot \Big( (\hat{M}^{(\Point,W),u}_{(g-g_h+g_{h'})(u)})_{\bob \bob'} \otimes (\tau_{h'}^W)_{\bob''} \Big) \;. \label{eq:qld-pulling-5}
1523	\end{align}
1524		Line~\eqref{eq:qld-pulling-5} follows from~\eqref{eq:qld-pulling-4} by expanding the definition of $\{ \hat{M}^{(\Point,W),u}_a\}$. Next, we argue that, on average over $u \in \F_q^m$,
1525	\begin{align}
1526			\text{\eqref{eq:qld-pulling-5}} &\approx_{\delta_S} \sum_{\substack{g,h,h': \\ (\coded(g)-h)\cdot \tilde{u} = a}} \Big((\hat{S}^W_g)_{\alice \alice'} \otimes (\tau_h^W)_{\alice''} \Big) \otimes \Big( (\hat{M}^{(\Point,W),u}_{(g-g_h+g_{h'})(u)})_{\bob \bob'} \otimes (\tau_{h'}^W)_{\bob''} \Big)~. \label{eq:qld-pulling-7}
1527			\end{align}
1528			We show this by bounding the magnitude of the difference. Using the fact that $\hat{S}^W_g$ and $\tau^W_h$ are projective, we have:
1529			\begin{align}
1530			&\E_u \sum_a \Big \|\sum_{\substack{g,h,h': \\ (\coded(g)-h)\cdot \tilde{u} = a}} (\hat{S}^W_g \cdot (\Id - \hat{M}^{(\Point,W),u}_{g(u)}))_{\alice \alice'} \otimes (\tau_h^W)_{\alice''} \otimes (\hat{M}^{(\Point,W),u}_{(g-g_h+g_{h'})(u)})_{\bob \bob'} \otimes (\tau_{h'}^W)_{\bob''} \, \ket{\hat{\psi}} \Big \|^2 \notag \\
1531	      =& \E_u \sum_{\substack{g,h,h'}} \bra{\hat{\psi}} \Big(((\Id - \hat{M}^{(\Point,W),u}_{g(u)}) \cdot \hat{S}^W_g \cdot (\Id - \hat{M}^{(\Point,W),u}_{g(u)}))_{\alice \alice'} \otimes (\tau_h^W)_{\alice''} \Big) \notag \\
1532	      & \hspace{20em} \cdot \Big( (\hat{M}^{(\Point,W),u}_{(g-g_h+g_{h'})(u)})^2_{\bob \bob'} \otimes (\tau_{h'}^W)_{\bob''} \Big) \ket{\hat{\psi}} \notag \\
1533			\leq& \E_u \sum_{g} \bra{\hat{\psi}} ((\Id - \hat{M}^{(\Point,W),u}_{g(u)}) \cdot \hat{S}^W_g \cdot (\Id - \hat{M}^{(\Point,W),u}_{g(u)}))_{\alice \alice'} \ket{\hat{\psi}}\label{eq:qld-pulling-8} \\
1534			\leq& \delta_S\;. \label{eq:qld-pulling-9}
1535			\end{align}
1536			The inequality in Line~\eqref{eq:qld-pulling-8} follows from the fact that for all $g,h$, the sum $\sum_{h'} (\hat{M}^{(\Point,W),u}_{(g-g_h+g_{h'})(u)})^2_{\bob \bob'} \otimes (\tau_{h'}^W)_{\bob''}$ is at most $\Id$. The inequality in Line~\eqref{eq:qld-pulling-9} follows from the second item of \Cref{lem:qld-constructing-the-paulis-helper} (to be proved below). 
1537			Next, we show that on average over $u \in \F_q^m$,
1538			\begin{align}
1539			\text{\eqref{eq:qld-pulling-7}} &=\sum_{\substack{g,h,g',h': \\ (\coded(g)-h)\cdot \tilde{u} = a}} \Big((\hat{S}^W_g)_{\alice \alice'} \otimes (\tau_h^W)_{\alice''} \Big) \cdot \Big( (\hat{S}^W_{g'} \cdot \hat{M}^{(\Point,W),u}_{(g-g_h+g_{h'})(u)})_{\bob \bob'} \otimes (\tau_{h'}^W)_{\bob''} \Big) \label{eq:qld-pulling-9a} \\
1540			&\approx_{O(\delta_S + \sqrt{\eps})} \sum_{\substack{g,h,g',h': \\ (g' - g_{h'})(u) = (g -g_h)(u) \\ (\coded(g)-h)\cdot \tilde{u} = a}} \Big((\hat{S}^W_g)_{\alice \alice'} \otimes (\tau_h^W)_{\alice''} \Big) \cdot \Big( (\hat{S}^W_{g'} \cdot \hat{M}^{(\Point,W),u}_{g'(u)})_{\bob \bob'} \otimes (\tau_{h'}^W)_{\bob''} \Big) \label{eq:qld-pulling-10} \\
1541			&\approx_{\delta_S} \sum_{\substack{g,h,g',h': \\ (g' - g_{h'})(u) = (g -g_h)(u) \\ (\coded(g)-h)\cdot \tilde{u} = a}} \Big((\hat{S}^W_g)_{\alice \alice'} \otimes (\tau_h^W)_{\alice''} \Big) \cdot \Big( (\hat{S}^W_{g'})_{\bob \bob'} \otimes (\tau_{h'}^W)_{\bob''} \Big) \label{eq:qld-pulling-11} \\
1542			&\approx_{md/q} \sum_{\substack{g,h,g',h': \\ g' - g_{h'} = g -g_h \\ (\coded(g)-h)\cdot \tilde{u} = a}} \Big((\hat{S}^W_g)_{\alice \alice'} \otimes (\tau_h^W)_{\alice''} \Big) \cdot \Big( (\hat{S}^W_{g'})_{\bob \bob'} \otimes (\tau_{h'}^W)_{\bob''} \Big)~. \label{eq:qld-pulling-12}
1543			\end{align}
1544			Before we justify the sequence of steps to go from Line~\eqref{eq:qld-pulling-7} to Line~\eqref{eq:qld-pulling-12}, we first argue how this establishes Line~\eqref{eq:qld-pulling-cons}, and hence the second item of the Lemma statement.
1545			
1546			Absorbing the error terms $O(md/q)$ and $O(\sqrt{\eps})$ into $\delta_S$, we have shown that 
1547			\[
1548			\Big ( \tilde{M}^{W,\tilde{u}}_a \Big)_{\alice \alice' \alice''} \approx_{\delta_S} \sum_{\substack{g,h,g',h': \\ g' - g_{h'} = g -g_h \\ (\coded(g)-h)\cdot \tilde{u} = a}} \Big((\hat{S}^W_g)_{\alice \alice'} \otimes (\tau_h^W)_{\alice''} \Big) \cdot \Big( (\hat{S}^W_{g'})_{\bob \bob'} \otimes (\tau_{h'}^W)_{\bob''} \Big).
1549			\]
1550			Note that the conditions $(\coded(g)-h)\cdot \tilde{u} = a$ and $g - g_h = g' - g_{h'}$ are equivalent to the conditions $(\coded(g') - h') \cdot \tilde{u} = a$ and $g - g_h = g' - g_{h'}$. Thus the expression in~\eqref{eq:qld-pulling-12} is symmetric between $g,h$ and $g',h'$, and so an analogous derivation shows that $\Big ( \tilde{M}^{W,\tilde{u}}_a \Big)_{\bob \bob' \bob''}$ is $\delta_S$-close to~\eqref{eq:qld-pulling-12}, and thus $\delta_S$-close to $\Big ( \tilde{M}^{W,\tilde{u}}_a \Big)_{\alice \alice' \alice''}$. This shows~\eqref{eq:qld-pulling-cons}. Since $\{ \tilde{M}^{W,\tilde{u}}_a \}$ is projective, by using Item 2 of \Cref{fact:agreement}, followed by \Cref{fact:data-processing}, and then followed by Item 1 of \Cref{fact:agreement}, we get for all $j \in \{1,\ldots,t\}$, on average over $\tilde{u} \in \F_q^\nqubits$,
1551	\[
1552		(\tilde{M}^{W,\tilde{u}}_{[\tr(e_j \cdot) = b]})_{\alice \alice' \alice''} \approx_{\delta_S} ( \tilde{M}^{W,\tilde{u}}_{[\tr(e_j \cdot) = b]})_{\bob \bob' \bob''}
1553	\]
1554	where the answer summation is over $b \in \F_2$. Finally, the second item of the Lemma follows from applying~\Cref{lem:povm-to-obs}.
1555	
1556			We now return to justifying the sequence of steps between Lines~\eqref{eq:qld-pulling-7} and~\eqref{eq:qld-pulling-12}. The equality in Line~\eqref{eq:qld-pulling-9a} follows by left-multiplying~\eqref{eq:qld-pulling-7} by $I_{\bob \bob'} = \sum_{g'} (\hat{S}^W_{g'})_{\bob \bob'}$. 
1557			
1558			\paragraph{The approximation in Line~\eqref{eq:qld-pulling-10}.} The approximation in Line~\eqref{eq:qld-pulling-10} follows by bounding the magnitude of the difference:	
1559	\begin{align}
1560			&\E_u \sum_a \Big \| \sum_{\substack{g,h,g',h': \\ (g' - g_{h'})(u) \neq (g -g_h)(u) \\ (\coded(g)-h)\cdot \tilde{u} = a}} \Big((\hat{S}^W_g)_{\alice \alice'} \otimes (\tau_h^W)_{\alice''} \Big) \cdot \Big( (\hat{S}^W_{g'} \cdot \hat{M}^{(\Point,W),u}_{(g-g_h+g_{h'})(u)})_{\bob \bob'} \otimes (\tau_{h'}^W)_{\bob''} \Big) \ket{\hat{\psi}} \Big \|^2 \notag \\
1561	&= \E_u \sum_{\substack{g,h,g',h': \\ (g' - g_{h'})(u) \neq (g -g_h)(u)}} \bra{\hat{\psi}} \Big(\hat{S}^W_g)_{\alice \alice'} \otimes (\tau_h^W)_{\alice''} \Big) \cdot \Big( (\hat{M}^{(\Point,W),u}_{(g-g_h+g_{h'})(u)} \cdot \hat{S}^W_{g'} \cdot \notag\\
1562	      &\hspace{20em}\hat{M}^{(\Point,W),u}_{(g-g_h+g_{h'})(u)})_{\bob \bob'} \otimes (\tau_{h'}^W)_{\bob''} \Big) \ket{\hat{\psi}} \notag \\
1563			&\leq \E_u \sum_{\substack{g,h,g',h',a': \\ a' \neq g'(u)}} \bra{\hat{\psi}} \Big(\hat{S}^W_g)_{\alice \alice'} \otimes (\tau_h^W)_{\alice''} \Big) \cdot \Big( (\hat{M}^{(\Point,W),u}_{a'} \cdot \hat{S}^W_{g'} \cdot \hat{M}^{(\Point,W),u}_{a'})_{\bob \bob'} \otimes (\tau_{h'}^W)_{\bob''} \Big) \ket{\hat{\psi}} \notag \\
1564			&= \E_u \sum_{g,a: a \neq g(u)} \bra{\hat{\psi}} (\hat{M}^{(\Point,W),u}_{a} \cdot \hat{S}^W_{g} \cdot \hat{M}^{(\Point,W),u}_{a})_{\bob \bob'} \ket{\hat{\psi}} \label{eq:qld-pulling-13a} \\
1565			&\approx_{O(\sqrt{\eps})} \E_u \sum_{g} \bra{\hat{\psi}} (\Id - \hat{M}^{(\Point,W),u}_{g(u)})_{\alice \bob''} \otimes ( \hat{S}^W_{g})_{\bob \bob'} \ket{\hat{\psi}}  \label{eq:qld-pulling-13} \\
1566			&\leq \delta_S \;. \label{eq:qld-pulling-14}
1567	\end{align}
1568	The approximation in Line~\eqref{eq:qld-pulling-13} follows from the following calculation:
1569	\begin{align}
1570		&\Big | \text{\eqref{eq:qld-pulling-13}} - \text{\eqref{eq:qld-pulling-13a}} \Big | \notag \\
1571		&\leq \Big | \E_u \sum_{g,a: a \neq g(u)} \bra{\hat{\psi}} (\hat{M}^{(\Point,W),u}_{a} \cdot \hat{S}^W_{g})_{\bob \bob'} \cdot ((\hat{M}^{(\Point,W),u}_{a})_{\alice \bob''} - (\hat{M}^{(\Point,W),u}_{a})_{\bob \bob'}) \ket{\hat{\psi}} \Big | \label{eq:qld-pulling-15} \\
1572		& \qquad + \Big | \E_u \sum_{g,a: a \neq g(u)} \bra{\hat{\psi}} ((\hat{M}^{(\Point,W),u}_{a})_{\alice \bob''} - (\hat{M}^{(\Point,W),u}_{a})_{\bob \bob'}) \cdot (\hat{S}^W_{g})_{\bob \bob'} \cdot (\hat{M}^{(\Point,W),u}_{a})_{\alice \bob''} \ket{\hat{\psi}} \Big | \label{eq:qld-pulling-15a}
1573	\end{align}
1574	Using Cauchy-Schwarz, we can bound the first term on the right hand side of the inequality by
1575	\begin{align}
1576		&\Biggl( \E_u \sum_{g,a: a \neq g(u)} \bra{\hat{\psi}} (\hat{M}^{(\Point,W),u}_{a} \cdot \hat{S}^W_{g} \cdot \hat{M}^{(\Point,W),u}_{a})_{\bob \bob'} \ket{\hat{\psi}}  \Biggr)^{1/2} \cdot \notag \\
1577		&\Biggl( \E_u \sum_{g,a: a \neq g(u)} \bra{\hat{\psi}} ((\hat{M}^{(\Point,W),u}_{a})_{\alice \bob''} - (\hat{M}^{(\Point,W),u}_{a})_{\bob \bob'}) \cdot (\hat{S}^W_{g})_{\bob \bob'} \cdot \notag\\
1578	  & \hspace{12em}((\hat{M}^{(\Point,W),u}_{a})_{\alice \bob''} - (\hat{M}^{(\Point,W),u}_{a})_{\bob \bob'})  \ket{\hat{\psi}}  \Biggr)^{1/2} \notag \\
1579		\leq & \sqrt{1} \cdot \sqrt{\eps} \notag
1580	\end{align}
1581	The inequality follows from the self-consistency of $\hat{M}^{(\Point,W),u}_{a}$, as established in \Cref{lem:qld-comm-cons}. Similarly, we can bound the second term in Line~\eqref{eq:qld-pulling-15a} by $\sqrt{\eps}$.
1582	This establishes the approximation in Line~\eqref{eq:qld-pulling-13}. 
1583	
1584	The inequality in Line~\eqref{eq:qld-pulling-14} follows from \Cref{eq:qld-s-point-con-bob} of \Cref{lem:qld-4-7}. This concludes the derivation of the approximation in Line~\eqref{eq:qld-pulling-10}.
1585	
1586	\paragraph{The approximation in Line~\eqref{eq:qld-pulling-11}.} We establish this approximation by bounding the magnitude of the difference:
1587	\begin{align*}
1588		&\E_u \sum_a \Big \| \sum_{\substack{g,h,g',h': \\ (g' - g_{h'})(u) = (g -g_h)(u) \\ (\coded(g)-h)\cdot \tilde{u} = a}} \Big((\hat{S}^W_g)_{\alice \alice'} \otimes (\tau_h^W)_{\alice''} \Big) \cdot \Big( (\hat{S}^W_{g'} \cdot (\Id - \hat{M}^{(\Point,W),u}_{g'(u)}))_{\bob \bob'} \otimes (\tau_{h'}^W)_{\bob''} \Big) \ket{\hat{\psi}} \Big \|^2 \\
1589		=& \E_u \sum_{\substack{g,h,g',h': \\ (g' - g_{h'})(u) \\ \quad = (g -g_h)(u)}} \bra{\hat{\psi}} (\hat{S}^W_g)_{\alice \alice'} \otimes (\tau_h^W)_{\alice''} \otimes ((\Id - \hat{M}^{(\Point,W),u}_{g'(u)}) \cdot \hat{S}^W_{g'} \cdot \notag \\
1590	  &\hspace{20em}(\Id - \hat{M}^{(\Point,W),u}_{g'(u)}))_{\bob \bob'} \otimes (\tau_{h'}^W)_{\bob''} \ket{\hat{\psi}}  \\
1591		\leq& \E_u \sum_{g'} \bra{\hat{\psi}} ((\Id - \hat{M}^{(\Point,W),u}_{g'(u)}) \cdot \hat{S}^W_{g'} \cdot (\Id - \hat{M}^{(\Point,W),u}_{g'(u)}))_{\bob \bob'} \ket{\hat{\psi}} \\
1592		\leq& \delta_S \;.
1593	\end{align*}
1594	The last inequality follows from the second item of \Cref{lem:qld-constructing-the-paulis-helper} (to be proved below). 
1595	
1596	\paragraph{The approximation in Line~\eqref{eq:qld-pulling-12}.} We establish this approximation by bounding the magnitude of the difference:
1597	\begin{align*}
1598		&\E_u \sum_a \Big \| \sum_{\substack{g,h,g',h': \\ g' - g_{h'} \neq g -g_h \\ (g' - g_{h'})(u) = (g -g_h)(u) \\ (\coded(g)-h)\cdot \tilde{u} = a}} \Big((\hat{S}^W_g)_{\alice \alice'} \otimes (\tau_h^W)_{\alice''} \Big) \cdot \Big( (\hat{S}^W_{g'})_{\bob \bob'} \otimes (\tau_{h'}^W)_{\bob''} \Big) \ket{\hat{\psi}} \Big \|^2 \\
1599		&= \sum_{\substack{g,h,g',h': \\ g' - g_{h'} \neq g -g_h}} \bra{\hat{\psi}} \Big((\hat{S}^W_g)_{\alice \alice'} \otimes (\tau_h^W)_{\alice''} \Big) \cdot \Big( (\hat{S}^W_{g'})_{\bob \bob'} \otimes (\tau_{h'}^W)_{\bob''} \Big) \ket{\hat{\psi}} \cdot \E_u \mathbf{1}[(g' - g_{h'})(u) = (g -g_h)(u)] \\
1600		&\leq md/q.
1601	\end{align*}
1602	The last inequality follows from the Schwartz-Zippel lemma: two distinct polynomials of total degree at most $md$ cannot agree on more than $md/q$ fraction of points. 
1603	
1604			
1605	
1606	\end{proof}
