732	\begin{lemma}[Unitarity and conjugation action of the swap unitaries]\label{lem:v-swap-conjugation}
733		\lean{MIPStarRE.QPBT.swapUnitary_mul_conjTranspose}
734		\lean{MIPStarRE.QPBT.conjTranspose_mul_swapUnitary}
735		\lean{MIPStarRE.QPBT.swapUnitary_conj_tildeObs}
